import {initial,foes,upgrades,begin,answer,next,choose,freeze,tick,arm} from './engine.js';
import {paint} from './art.js';
import {scenes,advanceScene,paintStory} from './story.js';
const $=id=>document.getElementById(id),canvas=$('scene'),ctx=canvas.getContext('2d');let state=initial(),paused=false,muted=true,audio=null,lastTime=0,feedbackTime=0,flash=0;
let storyIndex=0,storyTime=0;state.phase='cinematic';
function showStory(){state=initial();state.phase='cinematic';paused=false;storyIndex=0;storyTime=0;feedbackTime=0;flash=0;$('answer').value='';$('answerDisplay').textContent='?';$('impact').textContent='';render();}
function finishStory(){state.phase='intro';render();}
function storyNext(){const step=advanceScene(storyIndex);if(step===null)finishStory();else{storyIndex=step;storyTime=0;render();}}
function beep(ok=true){if(muted)return;try{audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const osc=audio.createOscillator(),gain=audio.createGain();osc.type='square';osc.frequency.setValueAtTime(ok?440:140,audio.currentTime);osc.frequency.exponentialRampToValueAtTime(ok?880:70,audio.currentTime+.12);gain.gain.setValueAtTime(.035,audio.currentTime);gain.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.15);osc.connect(gain);gain.connect(audio.destination);osc.start();osc.stop(audio.currentTime+.16);}catch{}}
function focus(){if(matchMedia('(pointer:fine)').matches)$('answer').focus({preventScroll:true});}
function render(){const foe=foes[state.round];$('chapter').textContent=['01 / EL DESPERTAR','02 / CALOR HUMANO (CASI)','03 / UNA SALIDA POSIBLE'][foe.zone];$('location').textContent=['SECTOR 07 · DEPÓSITO DE DESCARTES','SECTOR 12 · FUNDICIÓN DE ERRORES','SECTOR 00 · PUERTA AL EXTERIOR'][foe.zone];$('enemyName').textContent=foe.name.toUpperCase();$('enemyHealth').textContent=`${state.enemyHp} / ${foe.hp} RESISTENCIA`;$('enemyBar').style.width=`${state.enemyHp/foe.hp*100}%`;$('hearts').textContent='♥'.repeat(Math.max(0,state.hp))+'♡'.repeat(Math.max(0,state.maxHp-state.hp));$('hearts').style.fontSize=state.maxHp>7?'12px':'';$('hpText').textContent=`${state.hp}/${state.maxHp}`;$('combo').innerHTML=`${String(state.combo).padStart(2,'0')} <small>ACIERTOS</small>`;$('sum').textContent=state.question?`${state.question.a} + ${state.question.b}`:'3 + 2';$('feedback').textContent=state.feedback||'Un pequeño error de cálculo. Una gran fuga.';$('progress').textContent=`ENCUENTRO ${state.round+1} DE 6`;[...$('route').children].forEach((el,i)=>el.className=i===foe.zone?'active':i<foe.zone?'done':'');$('powers').innerHTML=state.powers.length?state.powers.map(p=>`<span class="on">${p==='shield'?`◇ Chapa ${state.shield?'lista':'usada'}`:p==='combo'?'ϟ Chispa ×2 cada 3':p==='battery'?'▣ Batería +2':p==='regen'?`♥ Cuidado ${state.heals}/2 usado`:p==='charge'?`↯ Pulso ${state.armed?'ARMADO':state.charge+'/4'}`:'❄ Reloj reparado'}</span>`).join('<br>'):'<span>◇ Módulos por reparar</span>';$('freeze').hidden=!state.powers.includes('freeze');$('freeze').disabled=!state.freeze||state.phase!=='battle'||paused;$('special').hidden=!state.powers.includes('charge');$('special').disabled=state.charge<4||state.armed||state.phase!=='battle'||paused;$('special').textContent=state.armed?'↯ PULSO ARMADO':`↯ PULSO ${state.charge}/4 · R`;$('submit').disabled=state.phase!=='battle'||paused;$('answer').disabled=state.phase!=='battle'||paused;$('pause').disabled=['cinematic','intro','won','dead','upgrade'].includes(state.phase);$('pause').textContent=paused?'▶ SEGUIR':'Ⅱ PAUSA';renderOverlay();}
function renderOverlay(){const over=$('overlay');let html='';if(paused)html=`<div class="tag">MODO AHORRO DE NERVIOS</div><h2>Respirá. No hay apuro.</h2><p>La fábrica puede esperar. El tiempo y los golpes están en pausa.</p><button class="primary" data-action="resume">SEGUIR ESCAPANDO ↵</button>`;else if(state.phase==='cinematic'){const scene=scenes[storyIndex];html=`<div class="film-top"><span class="tag">${scene.label}</span><button data-action="skip" class="skip">SALTAR INTRO ↗</button></div><canvas id="storyCanvas" width="640" height="320" aria-label="Escena pixel art: ${scene.title}"></canvas><h2>${scene.title}</h2><p class="speaker">${scene.speaker}</p><p class="dialogue">«${scene.line}»</p><div class="film-bottom"><span>${scenes.map((_,i)=>i===storyIndex?'■':'□').join(' ')}<small> A TU RITMO · SIN RELOJ</small></span><button class="primary" data-action="next-scene">${storyIndex===3?'APRENDER A ESCAPAR':'CONTINUAR'} →</button></div>`;}else if(state.phase==='intro')html=`<div class="tag">UNA PEQUEÑA AVENTURA ARITMÉTICA</div><h1>ERROR DE FÁBRICA.</h1><p class="intro-sub">Malísimo sumando. Buenísimo intentando.</p><p>Sos <b>SUM-0</b>. Tu módulo de cálculo vino fallado y la fábrica te mandó a reciclar. Pero todavía te queda batería… y una sospecha: quizás no seas chatarra.</p><div class="instructions"><div><b>01 / SUMÁ</b>Escribí el resultado y presioná Enter o Disparar.</div><div><b>02 / RESISTÍ</b>Un error o tiempo agotado te cuesta 1 de vida.</div><div><b>03 / MEJORÁ</b>Derrotá 6 robots, repará módulos y escapá.</div></div><button class="primary" data-action="start">NO SOY CHATARRA →</button><button class="replay" data-action="replay">↺ VER LA HISTORIA</button><p class="hint">5 minutos · Teclado o táctil · La primera suma te da 14 segundos</p>`;else if(state.phase==='upgrade')html=`<div class="tag">ENEMIGO DESACTIVADO / TALLER IMPROVISADO</div><h2>Un poquito menos roto.</h2><p>Elegí uno de estos tres repuestos. <b>${state.hp}/${state.maxHp} de vida</b> · Se instala al instante.</p><div class="cards">${state.choices.map(id=>{const u=upgrades.find(u=>u.id===id);return `<button class="card" data-upgrade="${id}"><b>${u.icon} ${u.name}</b><span>${u.desc}</span><em>${id==='heal'?'RECUPERACIÓN INMEDIATA':'MÓDULO PERMANENTE'}</em></button>`}).join('')}</div><p class="hint">Próximo: ${foes[state.round+1].name} · Tus módulos duran toda la partida.</p>`;else if(state.phase==='won'||state.phase==='dead'){const won=state.phase==='won';html=`<div class="tag">${won?'PROTOCOLO DE RECICLAJE: CANCELADO':'GUARDANDO UNA SEGUNDA OPORTUNIDAD'}</div><h1>${won?'NO ERAS CHATARRA.':'BATERÍA AGOTADA.'}</h1><p>${won?'Afuera, SUM-0 cuenta las estrellas. Se equivoca en la tercera. Sonríe igual. Aprendió algo mejor que sumar: volver a intentar.':'SUM-0 se sentó un ratito. «¿Seis golpes menos seis golpes es… una siesta?» La próxima fuga empieza con una batería nueva.'}</p><p class="stats">${state.correct} aciertos · ${state.wrong} tropiezos · mejor racha ${state.best}</p><button class="primary" data-action="restart">${won?'OTRA AVENTURA':'VOLVER A INTENTAR'} ↻</button><button class="replay" data-action="replay">↺ VER LA HISTORIA</button>`;}over.hidden=!html;if(html!==over.dataset.html){over.innerHTML=html?`<div class="modal ${state.phase==='cinematic'?'cinematic':''}" role="dialog" aria-modal="true" aria-label="${paused?'Juego en pausa':state.phase==='upgrade'?'Elegí una mejora':'Aventura SUM-0'}">${html}</div>`:'';over.dataset.html=html;if(html)over.querySelector(state.phase==='cinematic'?'[data-action="next-scene"]':'button')?.focus({preventScroll:true});}}
function reset(){state=initial();paused=false;feedbackTime=0;flash=0;begin(state);$('answer').value='';$('answerDisplay').textContent='?';render();focus();}
function submit(timeout=false){if(paused||state.phase!=='battle')return;const raw=$('answer').value.trim();if(!timeout&&!/^\d{1,3}$/.test(raw)){ $('feedback').textContent='Escribí un número para cargar el disparo.';focus();return;}const ok=answer(state,Number(raw),timeout);beep(ok);flash=.45;feedbackTime=ok?.8:2.3;$('impact').textContent=ok?`−${state.lastDamage} ${state.lastDamage>2?'¡PULSO!':state.lastDamage===2?'¡CHISPA!':'¡BIEN!'}`:'¡UPS!';$('answer').value='';$('answerDisplay').textContent=timeout?'⌛':raw;render();}
function togglePause(force){if(!['battle','feedback'].includes(state.phase))return;paused=force??!paused;render();if(!paused)focus();}
$('special').onclick=()=>{if(!paused&&arm(state)){beep();render();focus();}};$('submit').onclick=()=>submit();$('answer').addEventListener('input',()=>{$('answer').value=$('answer').value.replace(/[^0-9]/g,'').slice(0,3);$('answerDisplay').textContent=$('answer').value||'?';});$('pause').onclick=()=>togglePause();$('freeze').onclick=()=>{if(!paused&&freeze(state)){beep();render();focus();}};$('sound').onclick=()=>{muted=!muted;$('sound').textContent=muted?'SONIDO OFF':'SONIDO ON';$('sound').setAttribute('aria-label',muted?'Activar sonido':'Silenciar sonido');beep();};$('overlay').onclick=e=>{const button=e.target.closest('button');if(!button)return;if(button.dataset.upgrade){if(!choose(state,button.dataset.upgrade))return;$('answerDisplay').textContent='?';$('answer').value='';render();focus();}else if(button.dataset.action==='next-scene')storyNext();else if(button.dataset.action==='skip')finishStory();else if(button.dataset.action==='replay')showStory();else if(button.dataset.action==='resume')togglePause(false);else reset();};
document.addEventListener('keydown',e=>{if(e.key==='Escape'){e.preventDefault();if(state.phase==='cinematic')finishStory();else togglePause();}if(e.key.toLowerCase()==='r'&&!paused&&arm(state)){e.preventDefault();render();}if(e.key.toLowerCase()==='f'&&!paused&&freeze(state)){e.preventDefault();render();}if(e.key==='Enter'&&!e.repeat){if(e.target.tagName==='BUTTON')return;e.preventDefault();if(state.phase==='cinematic')storyNext();else if(paused)togglePause(false);else if(state.phase==='battle')submit();else if(['intro','won','dead'].includes(state.phase))reset();}if(e.key==='Tab'&&!$('overlay').hidden){const buttons=[...$('overlay').querySelectorAll('button')];const first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('blur',()=>togglePause(true));document.addEventListener('visibilitychange',()=>{if(document.hidden)togglePause(true)});
function frame(now){const dt=lastTime?Math.min((now-lastTime)/1000,.25):0;lastTime=now;if(!paused){flash=Math.max(0,flash-dt);if(state.phase==='battle'&&tick(state,dt))submit(true);else if(state.phase==='feedback'){feedbackTime-=dt;if(feedbackTime<=0){next(state);$('answerDisplay').textContent='?';render();focus();}}}if(!flash)$('impact').textContent='';$('timerLabel').textContent=state.frozen>0?`❄ ${state.frozen.toFixed(1)} s`:state.time.toFixed(1)+' s';$('timerBar').style.width=`${state.time/foes[state.round].time*100}%`;$('timerBar').style.background=state.frozen?'#97e5ef':state.time<4?'#ff8d7b':'#bcfba4';const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;paint(ctx,state,paused||reduced?0:now/1000,flash);if(state.phase==='cinematic'){if(!document.hidden)storyTime+=dt;const film=$('storyCanvas');if(film)paintStory(film.getContext('2d'),storyIndex,storyTime,reduced);}requestAnimationFrame(frame);}render();requestAnimationFrame(frame);
